(function(){'use strict';
var DATA={"label": "Model Drift Monitor - Signature build-tool concept", "rows": [["scikit-learn", "79"], ["  scikit-learn ", "70"], ["PyTorch", "35"], ["TensorFlow", "58"], ["  TensorFlow ", "24"], ["XGBoost", "27"], ["k-means clustering", "87"], ["  k-means clustering ", "20"], ["", ""], ["scikit-learn", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
